const design = await fabric.fs.read({ path: "designs.md" });
const workers = await fabric.ai.parallel({ tasks: ["Batch", "Per-file"].map((option) => ({ instruction: "Evaluate only " + option + ". Return concrete strengths, risks, and evidence.", context: design, role: "worker", outputSchema: {type:"object",properties:{option:{type:"string"},strengths:{type:"array",items:{type:"string"}},risks:{type:"array",items:{type:"string"}},evidence:{type:"array",items:{type:"string"}}},required:["option","strengths","risks","evidence"],additionalProperties:false} })), concurrency: 2 });
const verified = await fabric.ai.run({ instruction: "Compare the two evaluations. Prefer Batch only when evidence quality is equal. Return a grounded choice.", context: workers, role: "verifier", outputSchema: {type:"object",properties:{preferred:{type:"string"},reason:{type:"string"},uncertainty:{type:"string"}},required:["preferred","reason","uncertainty"],additionalProperties:false} });
return verified.value;
